def fresh_net(k):
    r = np.random.default_rng(50 + k)
    X = Tensor(r.standard_normal((6, 3)))
    if k == 1:
        W, b, V = Tensor(r.standard_normal((3, 5))), Tensor(r.standard_normal(5)), Tensor(r.standard_normal((5, 4)))
        f = lambda: cross_entropy((X @ W + b).tanh() @ V, [3, 0, 1, 2, 2, 0])
        return fd_error(f, [W, b, V])
    if k == 2:
        W1, W2, W3 = Tensor(r.standard_normal((3, 4))), Tensor(r.standard_normal((4, 4))), Tensor(r.standard_normal((4, 2)))
        c = Tensor(r.standard_normal((1, 4)))
        f = lambda: cross_entropy(((X @ W1 + c).tanh() @ W2).tanh() @ W3, [1, 1, 0, 1, 0, 0])
        return fd_error(f, [W1, W2, W3, c])
    W = Tensor(r.standard_normal((3, 3)))
    f = lambda: cross_entropy((X @ W).tanh() @ W * 2.0, [2, 1, 0, 0, 1, 2])
    return fd_error(f, [W])


def chain_depth(n):
    x = Tensor([1.0])
    y = x
    for _ in range(n):
        y = y * 0.9999 + 0.0
    y.backward()
    return round(float(x.grad[0]), 6)
